int cropWidth = Math.min(10, sourceImage.getWidth());
int cropHeight = Math.min(10, sourceImage.getHeight());

net.coobird.thumbnailator.geometry.Position pos = new net.coobird.thumbnailator.geometry.Coordinate(0, 0);
net.coobird.thumbnailator.geometry.Size dim = new net.coobird.thumbnailator.geometry.AbsoluteSize(cropWidth, cropHeight);
net.coobird.thumbnailator.geometry.Region cropRegion = new net.coobird.thumbnailator.geometry.Region(pos, dim);

java.awt.image.BufferedImage thumbnail = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
        .sourceRegion(cropRegion)
        .scale(1.0)
        .asBufferedImage();

assert thumbnail.getWidth() == cropWidth : "Expected width " + cropWidth + ", got " + thumbnail.getWidth();
assert thumbnail.getHeight() == cropHeight : "Expected height " + cropHeight + ", got " + thumbnail.getHeight();

System.out.println("__CHECK__ Region " + thumbnail.getWidth() + "x" + thumbnail.getHeight());
